var neuroCompanyStatusData = {"reviewed":"2026-09-15","scope":"Selected implantable neurotechnology programs, including cortical, endovascular and retinal devices. This review does not cover all companies in the wider atlas.","companies":[{"id":"neuralink","name":"Neuralink","stage":"Human trials underway","headline":"Human implantation began in January 2024.","summary":"Neuralink is testing its implanted N1 interface in people. Its current trials page lists device control and speech restoration as active; visual restoration is upcoming.","scope":"Investigational BCI. Trial permission and recruitment are separate from marketing approval or demonstrated benefit.","facts":[{"title":"21 enrolled participants","text":"Company-reported total across its trials as of 28 January 2026. This is a dated enrollment count, not a current implant count.","refs":["two-years"],"date":"2026-01-28"},{"title":"Six directly sponsored registrations","text":"ClinicalTrials.gov records include PRIME, CAN-PRIME, UAE-PRIME, GB-PRIME, CONVOY and VOICE. Registry statuses have their own update dates.","refs":["registry"],"date":"2026-09-15"},{"title":"Electrode expansion remains a plan","text":"The January update proposed increasing the electrode count from about 1,000 to 3,000. That announcement alone does not establish a deployed 3,000-electrode implant.","refs":["two-years"],"date":"2026-01-28"}],"sources":[{"id":"first","title":"PRIME progress: first human implant","url":"https://neuralink.com/updates/prime-study-progress-update/","kind":"Company update","checkedAt":"2026-09-15","scope":"Page content read.","published":"2024-04-12"},{"id":"two-years","title":"Two years of Telepathy","url":"https://neuralink.com/updates/two-years-of-telepathy/","kind":"Company update","checkedAt":"2026-09-15","scope":"Rendered update read, including enrollment and prospective engineering plans.","published":"2026-01-28"},{"id":"trials","title":"Current clinical-trial programs","url":"https://neuralink.com/trials/","kind":"Company trial page","checkedAt":"2026-09-15","scope":"Rendered page read: device-control and speech active; visual-prosthesis upcoming."},{"id":"registry","title":"PRIME registry record","url":"https://clinicaltrials.gov/study/NCT06429735","kind":"ClinicalTrials.gov","checkedAt":"2026-09-15","scope":"Structured API read for all six exact lead-sponsor records; dates below refer to each record’s last update.","published":"2026-01-09"}],"headlineRefs":["first"],"summaryRefs":["trials"],"scopeRefs":["registry"],"registry":{"checkedAt":"2026-09-15","queryUrl":"https://clinicaltrials.gov/api/v2/studies?query.spons=Neuralink&pageSize=100&format=json","studies":[{"nctId":"NCT07127172","title":"GB-PRIME: An Early Feasibility Study of a Precise Robotically Implanted Brain-Computer Interface for the Control of External Devices","sponsor":"Neuralink Corp","status":"RECRUITING","statusUpdated":"2025-08-17","start":{"date":"2025-07-31","type":"ACTUAL"},"enrollment":{"count":7,"type":"ESTIMATED"}},{"nctId":"NCT06700304","title":"CAN-PRIME: Precise Robotically Implanted Brain-Computer Interface for the Control of External Devices","sponsor":"Neuralink Corp","status":"RECRUITING","statusUpdated":"2025-05-31","start":{"date":"2024-11-20","type":"ACTUAL"},"enrollment":{"count":6,"type":"ESTIMATED"}},{"nctId":"NCT06992596","title":"UAE-PRIME: A Feasibility Study of a Precise Robotically Implanted Brain-Computer Interface for the Control of External Devices","sponsor":"Neuralink Corp","status":"RECRUITING","statusUpdated":"2025-06-05","start":{"date":"2025-05-09","type":"ACTUAL"},"enrollment":{"count":10,"type":"ESTIMATED"}},{"nctId":"NCT06710626","title":"Control of Assistive Devices Via Brain-Computer Interface Technology","sponsor":"Neuralink Corp","status":"ENROLLING_BY_INVITATION","statusUpdated":"2025-06-05","start":{"date":"2024-11-25","type":"ACTUAL"},"enrollment":{"count":3,"type":"ESTIMATED"}},{"nctId":"NCT06429735","title":"Precise Robotically IMplanted Brain-Computer InterfacE","sponsor":"Neuralink Corp","status":"RECRUITING","statusUpdated":"2026-01-09","start":{"date":"2024-01-09","type":"ACTUAL"},"enrollment":{"count":15,"type":"ESTIMATED"}},{"nctId":"NCT07224256","title":"VOICE: An Early Feasibility Study of a Precise Robotically Implanted Brain-Computer Interface for Communication Restoration","sponsor":"Neuralink Corp","status":"RECRUITING","statusUpdated":"2025-11-04","start":{"date":"2025-10-03","type":"ACTUAL"},"enrollment":{"count":6,"type":"ESTIMATED"}}],"scope":"Exact lead sponsor Neuralink Corp; excludes a collaborator-only result. Enrollment targets are not actual participants and may overlap across studies."},"checkedAt":"2026-09-15"},{"id":"synchron","name":"Synchron","stage":"Human clinical studies and participant demonstrations","headline":"An endovascular BCI already used in human studies.","summary":"Stentrode records from a blood vessel near the motor cortex. Synchron’s current website describes clinical work in the United States and Australia.","scope":"The current site labels the device investigational and says it has no commercial approval in any geography.","facts":[{"title":"COMMAND: six implanted participants","text":"The company’s 2024 report describes 12-month follow-up and digital motor outputs in all six study participants. This small feasibility study is not a population-wide efficacy estimate.","refs":["command"],"date":"2024-09-30"},{"title":"Everyday device integration","text":"A 2025 company demonstration showed a COMMAND participant using an iPad through Apple’s BCI input protocol. A demonstration is distinct from a controlled clinical outcome.","refs":["ipad"],"date":"2025-08-04"}],"sources":[{"id":"home","title":"Synchron: current program and investigational status","url":"https://synchron.com/","kind":"Company website","checkedAt":"2026-09-15","scope":"Page content read."},{"id":"research","title":"Synchron publications and research","url":"https://synchron.com/research","kind":"Company publication index","checkedAt":"2026-09-15","scope":"Page content read."},{"id":"command","title":"COMMAND 12-month results announcement","url":"https://www.businesswire.com/news/home/20240930433219/en/Synchron-Announces-Positive-Results-from-U.S.-COMMAND-Study-of-Endovascular-Brain-Computer-Interface","kind":"Company press release","checkedAt":"2026-09-15","scope":"Page content read.","published":"2024-09-30"},{"id":"ipad","title":"COMMAND participant: iPad demonstration","url":"https://www.businesswire.com/news/home/20250804537175/en/Synchron-Debuts-First-Thought-Controlled-iPad-Experience-Using-Apples-New-BCI-Human-Interface-Device-Protocol","kind":"Company press release","checkedAt":"2026-09-15","scope":"Page content read.","published":"2025-08-04"}],"headlineRefs":["command"],"summaryRefs":["home"],"scopeRefs":["home"],"checkedAt":"2026-09-15"},{"id":"precision-neuroscience","name":"Precision Neuroscience","stage":"Human studies + temporary electrode clearance","headline":"Layer 7 has human-study experience and a defined FDA clearance.","summary":"Precision’s current homepage reports 95+ clinical-study patients. This undated company total does not establish 95 chronic wireless BCI implants.","scope":"FDA K242618 covers Layer 7-T cortical electrodes for temporary use of less than 30 days. The cleared device is wired and has no software or wireless capability. Precision’s full BCI remains investigational.","facts":[{"title":"Read the actual clearance","text":"FDA’s decision is dated 30 March 2025; the company announced it on 17 April. The cleared use is cortical recording, monitoring and stimulation for brain mapping; continuous stimulation is excluded.","refs":["fda","clearance"],"date":"2025-03-30"},{"title":"Different stages of one platform","text":"Short intraoperative recordings, temporary electrode use and a fully implanted wireless BCI are distinct evidence categories. The April 2025 announcement reported 37 patients, before the later homepage total.","refs":["clearance","home"],"date":"2025-04-17"}],"sources":[{"id":"home","title":"Precision: current clinical program","url":"https://www.precisionneuro.io/","kind":"Company website","checkedAt":"2026-09-15","scope":"Homepage read; 95+ is an undated company total observed on the review date."},{"id":"fda","title":"FDA K242618: decision, indications and device description","url":"https://www.accessdata.fda.gov/cdrh_docs/pdf24/K242618.pdf","kind":"FDA decision","checkedAt":"2026-09-15","scope":"Decision, indications, device description and contraindications read: temporary use, wired passive device, and stimulation limited to brain mapping rather than continuous stimulation.","published":"2025-03-30"},{"id":"clearance","title":"Layer 7 clearance announcement","url":"https://www.precisionneuro.io/articles/company-news/precision-neuroscience-receives-fda-clearance-for-high-resolution-cortical-electrode-array","kind":"Company update","checkedAt":"2026-09-15","scope":"Page content read.","published":"2025-04-17"}],"headlineRefs":["fda","home"],"summaryRefs":["home"],"scopeRefs":["fda","home"],"checkedAt":"2026-09-15"},{"id":"paradromics","name":"Paradromics","stage":"Long-term human early-feasibility study","headline":"First long-term participant implanted in June 2026.","summary":"On 14 September 2026, Paradromics reported real-time speech and text communication by its first Connexus participant in the Connect-One study.","scope":"Connexus is investigational. The September result is a company report from one participant; it does not supply a generalizable accuracy or long-term outcome estimate.","facts":[{"title":"Communication milestone","text":"The report describes participant-selected speech, answers to open-ended questions and a family phone call. It distinguishes attempted and imagined speech observations.","refs":["speech"],"date":"2026-09-14"},{"title":"A study linking three clinical teams","text":"The announcement identifies UC Davis lead investigator David Brandman, Mass General Brigham’s Daniel Rubin, and University of Michigan clinical teams. FDA IDE permission was received in November 2025.","refs":["speech"],"date":"2026-09-14"}],"sources":[{"id":"speech","title":"Connexus participant: speech communication update","url":"https://paradromics.com/news/paradromics-achieves-real-time-speech-connexus-brain-computer-interface/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Page content read.","published":"2026-09-14"},{"id":"news","title":"Paradromics dated news index","url":"https://paradromics.com/news/","kind":"Company news index","checkedAt":"2026-09-15","scope":"Read June implantation, August study expansion and September speech announcements on the dated index."}],"headlineRefs":["speech"],"summaryRefs":["speech"],"scopeRefs":["speech"],"checkedAt":"2026-09-15"},{"id":"blackrock-neurotech","name":"Blackrock Neurotech","stage":"Established human research platform","headline":"Human BCI research is already established on Blackrock hardware.","summary":"The current company website describes participants using intracortical interfaces for typing, communication and robotic control. Its FAQ separately describes MoveAgain as an upcoming clinical system.","scope":"Human use of research hardware does not establish market authorization of a complete BCI product. The 2021 MoveAgain announcement reports Breakthrough Device designation, not marketing clearance.","facts":[{"title":"Research use and product status differ","text":"The Utah Array is used in selected human clinical trials and neural-circuit research. Hardware supplied to studies and a finished commercial BCI must be tracked separately.","refs":["faq"]},{"title":"A dated regulatory milestone","text":"MoveAgain received FDA Breakthrough Device designation in November 2021. The announcement’s planned 2022 commercialization was a forecast, not evidence that launch happened.","refs":["breakthrough"],"date":"2021-11-16"}],"sources":[{"id":"home","title":"Blackrock: human research examples","url":"https://blackrockneurotech.com/","kind":"Company website","checkedAt":"2026-09-15","scope":"Page content read."},{"id":"faq","title":"Blackrock: Utah Array and MoveAgain FAQ","url":"https://blackrockneurotech.com/faq/","kind":"Company FAQ","checkedAt":"2026-09-15","scope":"Page content read."},{"id":"breakthrough","title":"MoveAgain Breakthrough Device designation","url":"https://blackrockneurotech.com/insights/blackrock-neurotechs-moveagain-brain-computer-interface-system-receives-breakthrough-device-designation-from-the-fda/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Page content read.","published":"2021-11-16"},{"id":"news","title":"Blackrock current news and research index","url":"https://blackrockneurotech.com/news/","kind":"Company publication index","checkedAt":"2026-09-15","scope":"Read dated entries through July 2026; a listed paper’s full results are not inferred from its title."}],"headlineRefs":["home","faq"],"summaryRefs":["home","faq"],"scopeRefs":["breakthrough"],"checkedAt":"2026-09-15"},{"id":"science-corp","name":"Science Corporation","stage":"PRIMA: European launch announced","headline":"Science announced PRIMA’s European commercial launch in July 2026.","summary":"PRIMA is a retinal prosthesis with human clinical evidence. Science reports CE marking for geographic atrophy caused by age-related macular degeneration; this milestone applies to PRIMA, not all of its neural-interface programs.","scope":"Science says PRIMA is not commercially available outside the EU/EEA. Its US Humanitarian Use Device designations still require a separate Humanitarian Device Exemption review and approval.","headlineRefs":["launch"],"summaryRefs":["launch","study"],"scopeRefs":["launch","hud"],"facts":[{"title":"Read the human study","text":"The single-arm study implanted 38 participants; 32 were evaluated at 12 months. Of those, 26 achieved the prespecified meaningful visual-acuity improvement. The paper reports 26 device/procedure-related serious adverse events in 19 participants.","refs":["study"],"date":"2025-10-20"},{"title":"Regulatory scope depends on geography and product","text":"The July announcements report a European launch and US designations. PRIMA stimulates surviving retinal cells using a photovoltaic implant and specialized glasses. These results are not evidence for a cortical or biohybrid implant.","refs":["launch","hud"],"date":"2026-07-22"}],"sources":[{"id":"launch","title":"PRIMA European commercial-launch announcement","url":"https://science.xyz/news/ce-mark/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Page content read.","published":"2026-07-22"},{"id":"hud","title":"PRIMA US Humanitarian Use Device designations","url":"https://science.xyz/news/hud-designation/","kind":"Company regulatory update","checkedAt":"2026-09-15","scope":"Page content read.","published":"2026-07-22"},{"id":"study","title":"PRIMA clinical study: full author manuscript","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7618305/","kind":"Peer-reviewed study","checkedAt":"2026-09-15","scope":"Abstract, study design, participant accounting, efficacy and safety sections read. Open-label, nonrandomized, single-arm study.","published":"2025-10-20"}],"checkedAt":"2026-09-15"},{"id":"motif-neurotech","name":"Motif Neurotech","stage":"RESONATE study authorized; enrollment not confirmed here","headline":"FDA trial permission announced for treatment-resistant depression.","summary":"Motif announced an Investigational Device Exemption for its RESONATE early-feasibility study on 27 April 2026. It plans to evaluate the wirelessly powered XCS system, including the DOT stimulator.","scope":"The sources read establish permission to conduct the study, with enrollment planned for 2026. They do not establish that the first RESONATE participant has been implanted or that depression efficacy has been demonstrated.","headlineRefs":["ide"],"summaryRefs":["ide"],"scopeRefs":["ide","registry"],"facts":[{"title":"What the study is designed to test","text":"The announcement identifies up to eight sites and a 12-month primary safety assessment. Symptom, quality-of-life and cognitive measures are planned outcomes.","refs":["ide"],"date":"2026-04-27"},{"title":"A patient-interest registry is a different record","text":"The company’s registry page invites interest in future study opportunities. An interest form does not establish enrollment in a clinical trial.","refs":["registry"]}],"sources":[{"id":"ide","title":"RESONATE FDA IDE announcement","url":"https://www.businesswire.com/news/home/20260427361988/en/Motif-Neurotech-Receives-FDA-Approval-to-Begin-First-Clinical-Trial-of-its-Therapeutic-BCI-for-Treatment-Resistant-Depression","kind":"Company press release","checkedAt":"2026-09-15","scope":"Page content read.","published":"2026-04-27"},{"id":"registry","title":"Motif patient-interest registry information","url":"https://motifneuro.tech/patient-registry","kind":"Company website","checkedAt":"2026-09-15","scope":"Page content read."},{"id":"news","title":"Motif newsroom","url":"https://motifneuro.tech/news","kind":"Company news index","checkedAt":"2026-09-15","scope":"Read announcements and linked April 2026 trial permission. No first RESONATE implant established by these pages."}],"checkedAt":"2026-09-15"},{"id":"neuroxess","name":"NeuroXess","stage":"Registration clinical study announced","headline":"NeuroXess announced its registration-study launch in July 2026.","summary":"The company reports a multicenter study of its fully implanted wireless system for upper-limb assistance after cervical spinal-cord injury. Its July account describes a flexible electrode placed on the cortical surface under the dura.","scope":"The July 27 company announcement reports entry into China’s innovative-device special review pathway. It describes registration as work still ahead; this milestone is not a marketing authorization.","headlineRefs":["gcp"],"summaryRefs":["gcp"],"scopeRefs":["review"],"facts":[{"title":"A clinical network for registration evidence","text":"The July 8 announcement identifies Mao Ying’s Huashan Hospital team and 15 collaborating hospitals. Study initiation does not establish a completed efficacy result or a participant total.","refs":["gcp"],"date":"2026-07-08"},{"title":"Human demonstrations precede the registration study","text":"The current site describes implanted participants controlling digital devices and using assistance for eating and drawing. These examples are company reports; their performance percentages should not be treated as a common benchmark across BCIs.","refs":["home"]}],"sources":[{"id":"gcp","title":"三全系统 GCP registration-study launch","url":"https://www.neuroxess.com/news/naohukejisanquannaojijiekouxitongzhengshiqidonggcpzhucelinchuangshiyan/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Chinese announcement read. Publication date is July 8; a later release gives July 7 as the launch date, so the summary uses month-level timing.","published":"2026-07-08"},{"id":"review","title":"Innovative-device special review announcement","url":"https://www.neuroxess.com/news/guoneishoukuannaohukejiziyanyingmoxiazhirushirouxingnaojijiekoujinrulusetongdao/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Page content read.","published":"2026-07-27"},{"id":"home","title":"NeuroXess current human-use examples","url":"https://www.neuroxess.com/","kind":"Company website","checkedAt":"2026-09-15","scope":"Page content read."}],"checkedAt":"2026-09-15"},{"id":"stairmed","name":"StairMed","stage":"Human implant studies reported","headline":"Human clinical work extends beyond the animal-electrode research.","summary":"StairMed’s current news page reports a second clinical participant controlling a wheelchair and robotic dog in December 2025. In March 2026, it announced plans for a larger registration study during the year.","scope":"The December report describes a participant milestone; the March announcement describes a future study plan. Neither establishes a completed registration trial or authorization to sell an implanted BCI.","headlineRefs":["news"],"summaryRefs":["news"],"scopeRefs":["news"],"facts":[{"title":"Keep acute recordings separate","text":"The April 17 company news entry describes support for a published human single-neuron recording study. It specifically describes acute recordings, which cannot establish chronic clinical performance.","refs":["news"],"date":"2026-04-17"},{"title":"Earlier institutional evidence","text":"A June 2025 Chinese Academy of Sciences report describes a participant implanted in March 2025 who learned computer tasks. The article reports the research team’s early follow-up; it is not a regulator decision.","refs":["cas"],"date":"2025-06-14"}],"sources":[{"id":"news","title":"StairMed clinical and research news","url":"https://www.stairmed.com/xinwenzaixian.html","kind":"Company news index","checkedAt":"2026-09-15","scope":"Chinese dated entries read: 17 Dec 2025 human use, 13 Mar 2026 registration-study plan, 17 Apr 2026 acute-recording research. One future-dated December 2026 listing was excluded."},{"id":"cas","title":"CAS: prospective human BCI study","url":"https://www.cas.cn/syky/202506/t20250614_5073157.shtml","kind":"Institutional research report","checkedAt":"2026-09-15","scope":"Page content read.","published":"2025-06-14"},{"id":"home","title":"StairMed current technology and clinical aims","url":"https://www.stairmed.com/","kind":"Company website","checkedAt":"2026-09-15","scope":"Page content read."}],"checkedAt":"2026-09-15"},{"id":"neuracle","name":"Neuracle","stage":"Restricted product authorization in China","headline":"China authorized a hand-grasp compensation system in March 2026.","summary":"The NMPA authorized an epidural BCI system that decodes brain signals to operate a pneumatic glove for a defined cervical spinal-cord injury population.","scope":"This authorization concerns a specific hand-function compensation system and indication in China; it does not establish authorization for other NEO applications or other countries.","headlineRefs":["nmpa"],"summaryRefs":["nmpa"],"scopeRefs":["nmpa"],"facts":[{"title":"Defined eligibility","text":"The regulator specifies ages 18–60, C2–C6 injury graded A–C, diagnosis over one year earlier, stability for at least six months after standard treatment, absent hand grasp and some remaining upper-arm function.","refs":["nmpa"],"date":"2026-03-13"},{"title":"Earlier chronic study","text":"Tsinghua reports a first NEO clinical implant on 24 October 2023 and a second on 19 December 2023. The January 2024 report describes home training with the first participant; these are historical milestones, not a current implant total.","refs":["tsinghua"],"date":"2024-01-30"}],"sources":[{"id":"nmpa","title":"First invasive BCI medical device authorized for marketing (NMPA notice reproduced by Shanghai regulator)","url":"https://yjj.sh.gov.cn/zjyw/20260313/04985a5fbe284e9c806ff5f370cb00b2.html","kind":"Regulator announcement","checkedAt":"2026-09-15","scope":"Full Chinese notice read, including named manufacturer, system components, epidural approach and restricted indication. Notice date is 13 March; body says approval occurred recently.","published":"2026-03-13"},{"id":"tsinghua","title":"Tsinghua and Xuanwu Hospital report the first wireless minimally invasive NEO clinical trial","url":"https://www.tsinghua.edu.cn/info/1175/109595.htm","kind":"Institutional research report","checkedAt":"2026-09-15","scope":"Full Chinese article read. Establishes Neuracle collaboration, 2023 implantation dates and reported early home use, not present-day efficacy or participant totals.","published":"2024-01-30"}],"checkedAt":"2026-09-15","reviewNotes":["The company homepage and news pages were attempted but returned empty content, timeouts or HTTP 429. This review uses the regulator’s full notice and Tsinghua’s institutional report; company-page content was not independently accessible."]},{"id":"cortec","name":"CorTec","stage":"Chronic human feasibility studies","headline":"Brain Interchange is implanted in people in a stroke-rehabilitation study.","summary":"CorTec’s current website reports three chronically implanted stroke participants at the University of Washington and, separately, 13 people studied during acute epilepsy recordings at Mayo Clinic.","scope":"Brain Interchange remains investigational. FDA trial permission and Breakthrough Device Designations do not constitute marketing authorization or establish rehabilitation benefit.","headlineRefs":["first"],"summaryRefs":["current"],"scopeRefs":["pipeline","designation"],"facts":[{"title":"First chronic implantation","text":"The company announced a late-July 2025 implantation at Harborview under an FDA Investigational Device Exemption. The study evaluates safety and whether cortical stimulation can improve upper-limb recovery.","refs":["first"],"date":"2025-07-29"},{"title":"Two different designations","text":"CorTec announced a second FDA Breakthrough Device Designation for communication in August 2026, alongside its April designation for stroke motor rehabilitation. These concern the same platform.","refs":["designation"],"date":"2026-08-31"},{"title":"Pipeline stages differ","text":"Its pipeline lists an active epilepsy investigation, recruiting INTENSE paralysis research at UMC Utrecht, and a depression first-in-human study still in planning. Recruitment does not confirm an implantation.","refs":["pipeline"]}],"sources":[{"id":"current","title":"CorTec: current clinical evidence summary","url":"https://cortec-neuro.com/","kind":"Company website","checkedAt":"2026-09-15","scope":"Homepage content read. Three chronic and 13 acute participants are separate company-reported cohorts; page gives no date for those counts."},{"id":"first","title":"First human implantation of a Brain-Computer Interface made in Germany","url":"https://cortec-neuro.com/news/first-human-implantation-of-a-bci-made-in-germany","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Article read, including late-July procedure, IDE, Harborview/UW, and exploratory study objectives.","published":"2025-07-29"},{"id":"pipeline","title":"Clinical Pipeline — Brain Interchange","url":"https://cortec-neuro.com/bci/clinical-pipeline","kind":"Company trial page","checkedAt":"2026-09-15","scope":"Full pipeline read, including study-specific statuses and explicit investigational-device disclaimer."},{"id":"designation","title":"CorTec receives second FDA Breakthrough Device Designation for Brain Interchange","url":"https://cortec-neuro.com/news/cortec-receives-second-fda-breakthrough-device-designation-for-brain-interchange","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Read indication descriptions and dates; this is a company report of designations, not a marketing decision.","published":"2026-08-31"}],"checkedAt":"2026-09-15"},{"id":"inbrain","name":"INBRAIN Neuroelectronics","stage":"Human intraoperative study","headline":"Enrollment completed for its first human graphene-electrode study.","summary":"ICN2 reported ten recruited patients, eight of whom underwent procedures with INBRAIN devices during brain-tumour surgery. The University of Manchester-sponsored study primarily evaluates safety.","scope":"These are intraoperative mapping and recording procedures, not evidence of chronic Parkinson’s treatment. Final study results were still pending in the April update; INBRAIN labels its devices investigational.","headlineRefs":["icn2"],"summaryRefs":["icn2"],"scopeRefs":["icn2","technology"],"facts":[{"title":"Interim safety reporting","text":"ICN2 reported no device-related adverse events during the procedures or through hospital discharge. This limited observation window does not establish long-term safety.","refs":["icn2"],"date":"2026-04-22"},{"title":"Mapping during awake surgery","text":"Some participants performed language tasks such as naming objects while the electrodes recorded activity. The source does not report a restored-speech outcome.","refs":["icn2"],"date":"2026-04-22"},{"title":"Commercialization remains a target","text":"The current technology page says it is working toward first product commercialization in 2027. Its patient registry invites interest in upcoming trials.","refs":["technology"]}],"sources":[{"id":"icn2","title":"Patient enrolment for first-in-human trial of ICN2-developed graphene electrodes is completed","url":"https://icn2.cat/en/news/5605-patient-enrolment-for-first-in-human-trial-of-icn2-developed-graphene-electrodes-is-completed","kind":"Institutional research report","checkedAt":"2026-09-15","scope":"Full report read: ten recruited, eight procedures, surgical setting, interim safety window and final results expected at end of 2026. No claim that final results are already available.","published":"2026-04-22"},{"id":"technology","title":"INBRAIN technology and development roadmap","url":"https://inbrain-neuroelectronics.com/technology/","kind":"Company website","checkedAt":"2026-09-15","scope":"Current page read, including investigational-use disclaimer and prospective 2027 commercialization target. Electrode capacity is not used as a human-study channel count."}],"checkedAt":"2026-09-15"},{"id":"neurosoft-bio","name":"Neurosoft Bioelectronics","stage":"Human intraoperative studies","headline":"Soft cortical electrodes have been tested during human epilepsy surgery.","summary":"The company’s February 2025 report describes a 64-channel stretchable interface used in the first two participants of a planned 12-patient study at UMC Utrecht.","scope":"The reported procedures are intraoperative recordings. They do not establish chronic therapeutic benefit; the company states that its brain interfaces remain investigational and unavailable for sale in the United States and Europe.","headlineRefs":["utrecht"],"summaryRefs":["utrecht"],"scopeRefs":["utrecht","current"],"facts":[{"title":"A study target, not enrollment achieved","text":"Twelve was the planned Utrecht study size in the February announcement. The two procedures reported there are a dated milestone, not a current total.","refs":["utrecht"],"date":"2025-02-27"},{"title":"Current company confirmation","text":"A July 2026 announcement says first-in-human studies have been conducted at UTHealth Houston and UMC Utrecht, without giving an updated patient count or long-term outcome.","refs":["current"],"date":"2026-07-07"},{"title":"AI development is separate","text":"The July announcement describes plans for neural AI models and motor-restoration applications. It does not report that these applications have been clinically validated.","refs":["current"],"date":"2026-07-07"}],"sources":[{"id":"utrecht","title":"High-channel-count soft and stretchable interface tested in human epilepsy surgery","url":"https://www.neurosoft-bio.com/onlinepr/20250227-64electrodes","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Full release read: 64 sensing channels, first two participants, intraoperative use and planned 12-patient study. No comparative-superiority claims retained.","published":"2025-02-27"},{"id":"current","title":"Neurosoft names a Vice President of NeuroAI","url":"https://www.neurosoft-bio.com/onlinepr/neurosoft-bioelectronics-names-sam-hosovsky-vice-president-of-neuroai","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Article and footer read. Dateline is 7 July 2026; website post label says 8 July. Current research locations and investigational disclaimer are explicit.","published":"2026-07-07"}],"checkedAt":"2026-09-15"},{"id":"axoft","name":"Axoft","stage":"Human intraoperative studies","headline":"Ultrasoft penetrating probes have recorded human brain activity during surgery.","summary":"Axoft’s first four FINESSE cases involved people undergoing brain-tumour resection in Panama, with recordings lasting 20 minutes. Its April 2026 update reports expanding human studies and a Mass General Brigham collaboration.","scope":"The documented Panama result is temporary implantation and removal, not a chronic home-use BCI result. Commercial availability of the Fleuron material does not establish authorization of Axoft’s implanted BCI.","headlineRefs":["finesse"],"summaryRefs":["finesse","update"],"scopeRefs":["finesse","update"],"facts":[{"title":"First four cases","text":"The April 2025 company release describes cortical and subcortical recordings during awake or anesthetized surgery in March and April. Reported signal stability covers the 20-minute recording period.","refs":["finesse"],"date":"2025-04-22"},{"title":"Broader clinical research","text":"The April 2026 update names cortical mapping, seizure-onset mapping around tumours and language tasks in the Mass General Brigham research collaboration. It does not establish a completed chronic implant trial.","refs":["update"],"date":"2026-04-29"},{"title":"Materials and implant development differ","text":"The company describes Fleuron as commercially available while U.S. regulatory approval of its implantable BCI remains a development objective.","refs":["update"],"date":"2026-04-29"}],"sources":[{"id":"finesse","title":"Axoft completes first four cases of FINESSE first-in-human study","url":"https://www.businesswire.com/news/home/20250422988411/en/Axoft-Successfully-Completes-First-Four-Cases-of-First-in-Human-Clinical-Study-of-its-Ultrasoft-High-Density-Brain-Computer-Interface","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Full company release read: four surgical cases, 20-minute recordings, implantation and explantation. Longer-duration preclinical claims are explicitly excluded from human evidence.","published":"2025-04-22"},{"id":"update","title":"Axoft raises Series A to advance global clinical trials","url":"https://www.businesswire.com/news/home/20260429285106/en/Axoft-Secures-%2455M-Series-A-to-Advance-Clinical-Trials-Globally-for-its-Bio-Inspired-Implantable-Brain-Computer-Interface","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Release linked by official Axoft news page read. Human-study expansion and materials commercialization distinguished. Exact global participant total omitted because headline says 11 while body says more than 11.","published":"2026-04-29"},{"id":"news","title":"Axoft official news chronology","url":"https://axoft.us/news","kind":"Company website","checkedAt":"2026-09-15","scope":"Current news chronology read through August 2026. Confirms company provenance of linked releases; latest materials announcement is not a new clinical outcome."}],"checkedAt":"2026-09-15"},{"id":"ability-neuro","name":"ABILITY Neurotech","stage":"Acute human recordings; chronic study recruiting","headline":"First intraoperative recordings reported; INTRECOM is recruiting separately.","summary":"ABILITY reported its first surgical signal-acquisition procedure at TUM in July 2026 under general anesthesia. Its current clinical-study page separately advertises recruitment at UMC Utrecht for long-term brain-signal communication research.","scope":"The July result is not an awake speech-decoding demonstration or chronic implantation outcome. A recruitment page does not confirm implantation; ABILITY states its system is investigational and not commercially available.","headlineRefs":["first","clinical"],"summaryRefs":["first","clinical"],"scopeRefs":["first","clinical"],"facts":[{"title":"First surgical test","text":"The first participant underwent system-performance testing and signal acquisition. The study plans up to five tumour-surgery participants and 20–30 minutes of recording per participant.","refs":["first"],"date":"2026-07-21"},{"title":"Long-term study design","text":"The Utrecht recruitment page describes an approximately one-year study, surgery to place surface recording electrodes, and home visits for communication training. These describe participation plans, not completed outcomes.","refs":["utrecht"]},{"title":"Separate next steps","text":"The July announcement proposes later awake speech and motor tasks and a subsequent long-term implantation study. Current INTRECOM recruitment must not be counted as a second completed implantation.","refs":["first","clinical"]}],"sources":[{"id":"first","title":"ABILITY announces first-in-human testing in an intraoperative study","url":"https://abilityneuro.com/press/fih-intraop/","kind":"Company announcement","checkedAt":"2026-09-15","scope":"Full release read: first case under general anesthesia, intended five-person acute study, future awake tasks and long-term study explicitly distinguished.","published":"2026-07-21"},{"id":"clinical","title":"ABILITY: INTRECOM Clinical Study","url":"https://abilityneuro.com/clinical-trial/","kind":"Company trial page","checkedAt":"2026-09-15","scope":"Current recruiting page read, including stated ethics approval, prospective implantation and home training, and investigational-device disclaimer."},{"id":"utrecht","title":"UMC Utrecht: participate in INTRECOM research","url":"https://neuroprothese.nl/en/participate-in-research-intrecom/","kind":"Institutional study page","checkedAt":"2026-09-15","scope":"Recruitment page linked by ABILITY read. Confirms study duration and planned home training; no implanted-participant count or completed outcomes given."}],"checkedAt":"2026-09-15"}]};
